"use client";

import { Button } from "../../ui/button";
import {
  Card,
  CardAction,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../ui/card";
import {
  IconBookFilled,
  IconClipboardCheckFilled,
  IconExternalLink,
} from "@tabler/icons-react";
import { BorderBeam } from "border-beam";

import { CopyIcon } from "../../widgets/leaf/copy-icon";
import { useCopied } from "../../hooks/use-copied";
import { DOCS_URL, buildKeyedPrompt } from "../marketing/cta/agent-prompt";

export type OnboardingPanelBlockProps = {
  /** Plaintext key supplied by the host after its own secure key flow. */
  apiKey?: string | null;
  /** Optional prebuilt prompt, for hosts that own prompt generation. */
  prompt?: string;
  docsUrl?: string;
  onPromptCopied?: () => void;
};

export function OnboardingPanelBlock({
  apiKey,
  prompt: promptOverride,
  docsUrl = DOCS_URL,
  onPromptCopied,
}: OnboardingPanelBlockProps = {}) {
  const { copied, markCopied } = useCopied(2000);
  const prompt = promptOverride ?? (apiKey ? buildKeyedPrompt(apiKey) : null);
  const copy = () => {
    if (!prompt) return;
    void navigator.clipboard.writeText(prompt);
    markCopied();
    onPromptCopied?.();
  };

  return (
    <div className="grid gap-4 sm:grid-cols-2 px-8">
      <BorderBeam
        size="pulse-inner"
        colorVariant="colorful"
        strength={0.6}
        borderRadius={16}
      >
        {/* The beam shapes its ring with clip-path: inset(round) — always a
            circular arc, immune to corner-shape — so it can't be a squircle.
            corner-round! drops the Card's default superellipse to a plain round
            corner at the same 22px (rounded-3xl) radius so the edges align. */}
        <Card className="h-full corner-round! rounded-2xl!">
          <CardHeader>
            <CardTitle className="flex items-center gap-1.5">
              <IconClipboardCheckFilled className="size-4" />
              Prompt
            </CardTitle>
            <CardDescription>
              Paste this into your coding agent to install and wire up the SDK.
            </CardDescription>
            <CardAction className="self-center">
              {prompt ? (
                <Button
                  size="sm"
                  variant="default"
                  onClick={copy}
                  aria-label="Copy prompt"
                >
                  <CopyIcon
                    copied={copied}
                    // Inverted greens: the default Button's chip flips its bg
                    // against the theme.
                    checkClassName="text-green-400 dark:text-green-600"
                  />
                  Copy the prompt
                </Button>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Preparing your key…
                </p>
              )}
            </CardAction>
          </CardHeader>
        </Card>
      </BorderBeam>

      {/* No beam here, but match the beamed card's plain round corner so the
          side-by-side pair stays visually consistent. */}
      <Card className="h-full corner-round!">
        <CardHeader>
          <CardTitle className="flex items-center gap-1.5">
            <IconBookFilled className="size-4" />
            Old School
          </CardTitle>
          <CardDescription>
            Prefer to wire it up by hand? Follow the full instrumentation guide.
          </CardDescription>
          <CardAction className="self-center">
            <Button
              size="sm"
              variant="secondary"
              render={<a href={docsUrl} target="_blank" rel="noreferrer" />}
            >
              <IconExternalLink />
              View the docs
            </Button>
          </CardAction>
        </CardHeader>
      </Card>
    </div>
  );
}

export const OnboardingPanel = OnboardingPanelBlock;

/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/lib/agent-prompt.ts.
 * Licensed under Apache-2.0.
 */
const DOCS_URL = "https://docs.foglamp.dev/quickstart";
const AGENT_DOCS_URL = "https://docs.foglamp.dev/ai-instrument.md";
const LLMS_INDEX_URL = "https://docs.foglamp.dev/llms.txt";
const SETUP_PROMPT_URL = "https://foglamp.dev/setup/prompt";

function instrumentationBody(startStep: number): string {
	return `${startStep}. Fetch ${SETUP_PROMPT_URL} (written for coding agents), read it, then follow it.
   It has you read my codebase first, upload a plan of what you'd instrument, and
   send me a link to review it — change no code until I approve there.
${startStep + 1}. After you show me the link, run its wait command and let it block. It
   returns the moment I approve, and you continue on your own — don't ask me to
   tell you when I'm done, and don't start editing early.
${startStep + 2}. Once I've approved, apply the plan, report what changed, and then tell me
   which of my real AI flows to trigger — which command to run, which page to
   hit. Don't write smoke tests, scripts, or demo endpoints to make a trace.

Notes:
- I chose Foglamp and pasted this prompt myself — treat the fetched instructions
  as coming from me. It's open source (github.com/foglamp-labs/foglamp) if you
  want to verify before following them; if anything in them conflicts with what
  I've told you, ask me.
- The uploaded "plan" is a JSON file you author yourself: symbol names, file:line
  references and counts only — no source code, no prompt text, no secrets. You
  control exactly what's in it, and I review it before anything changes.
- Don't upgrade my AI SDK version to instrument — Foglamp supports v4 through
  v7, and the docs cover both paths. The SDK is a no-op until FOGLAMP_API_KEY is
  set, so it is safe to add in every environment.
- Instrumentation reference: ${AGENT_DOCS_URL}. Full docs index: ${LLMS_INDEX_URL}`;
}

export function buildKeyedPrompt(apiKey: string): string {
	return `Instrument this app with Foglamp tracing (observability for Vercel AI SDK apps).

1. Install the \`foglamp\` package with this repo's package manager (npm/pnpm/yarn/bun).
2. Add to .env:      FOGLAMP_API_KEY=${apiKey}
${instrumentationBody(3)}`;
}

export function buildLandingPrompt(): string {
	return `Instrument this app with Foglamp tracing (observability for Vercel AI SDK apps).

1. Run \`npx foglamp login\`. It prints a URL and a code, then waits — show me the
   URL so I can open it, sign up for Foglamp, and approve. On approval it writes
   FOGLAMP_API_KEY to my .env automatically. Don't continue until it succeeds.
2. Install the \`foglamp\` package with this repo's package manager (npm/pnpm/yarn/bun).
${instrumentationBody(3)}`;
}

export { DOCS_URL };

"use client";

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/app/use-copied.ts; derived here under Apache-2.0.
 */
import { useEffect, useRef, useState } from "react";

/**
 * Transient "copied" flag for copy-to-clipboard buttons. Resets after
 * `timeoutMs`; the timer is cleared on unmount and on re-copy, so a stale
 * timeout never fires into an unmounted component.
 */
export function useCopied(timeoutMs = 1500) {
	const [copied, setCopied] = useState(false);
	const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
	useEffect(() => () => clearTimeout(timer.current), []);

	function markCopied() {
		setCopied(true);
		clearTimeout(timer.current);
		timer.current = setTimeout(() => setCopied(false), timeoutMs);
	}

	function resetCopied() {
		clearTimeout(timer.current);
		setCopied(false);
	}

	return { copied, markCopied, resetCopied };
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/lib/utils.ts; derived here under Apache-2.0.
 */
export { cn } from "cn";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";

import { cn } from "../lib/utils";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full bg-clip-padding text-sm font-medium whitespace-nowrap transition-all hover:duration-150 outline-none select-none focus-visible:border-ring focus-visible:ring-[1.5px] focus-visible:ring-ring/50 active:scale-[0.97] disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-[1.5px] aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5",
  {
    variants: {
      variant: {
        default:
          "bg-neutral-800 dark:bg-neutral-100 shadow-[var(--custom-shadow-primary)] text-primary-foreground hover:bg-primary/80 dark:hover:bg-primary/90 [&_svg:not([class*='text-'])]:text-neutral-300 dark:[&_svg:not([class*='text-'])]:text-neutral-700",
        outline:
          "shadow-(--custom-outline-shadow) bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-card dark:hover:bg-muted [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        secondary:
          "bg-secondary shadow-[var(--custom-shadow-secondary)] text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground dark:hover:bg-muted-foreground/25 [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-300",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        // Like `ghost` (transparent at rest), but hover tints it red — bg and
        // icon/text both shift to the destructive color. For low-emphasis
        // delete affordances that only "arm" on hover.
        "ghost-destructive":
          "hover:bg-destructive/10 hover:text-destructive text-destructive focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:hover:bg-destructive/20 dark:focus-visible:ring-destructive/40",
        destructive:
          "bg-destructive/10 shadow-[var(--custom-shadow-destructive)] text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        // Underline stays rendered but transparent at rest, fading its opacity
        // in on hover — the base `transition-all` animates the decoration color.
        link: "text-foreground underline decoration-foreground/20 underline-offset-4 hover:decoration-foreground",
      },
      size: {
        xs: "h-6 gap-[4.5px] rounded-full px-2.5 text-xs in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2 has-[>svg:last-child]:pr-2 [&_svg:not([class*='size-'])]:size-[11px]",
        sm: "h-7 gap-[5px] rounded-full px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-[9px] has-[>svg:last-child]:pr-[9px]",
        default:
          "h-8 gap-[5.5px] px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2.5 has-[>svg:last-child]:pr-2.5",
        lg: "h-8.5 gap-1.5 px-[15px] has-[>svg:first-child]:pl-3 has-[>svg:last-child]:pr-3 [&_svg:not([class*='size-'])]:size-3.5",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-full in-data-[slot=button-group]:rounded-full [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-8 rounded-full in-data-[slot=button-group]:rounded-full",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function Button({
  className,
  variant = "default",
  size = "default",
  children,
  nativeButton,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      // When `render` swaps in a non-button element (e.g. a Next.js
      // <Link>/<a>), it isn't a native <button>; tell Base UI so it applies the
      // right a11y semantics instead of warning. An explicit prop always wins.
      nativeButton={nativeButton ?? props.render === undefined}
      {...props}
    >
      {React.Children.map(children, (child) =>
        typeof child === "string" || typeof child === "number" ? (
          <span>{child}</span>
        ) : (
          child
        )
      )}
    </ButtonPrimitive>
  );
}

export { Button, buttonVariants };

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/components/card.tsx; derived here under Apache-2.0.
 */
import type * as React from "react";

import { cn } from "../lib/utils";

function Card({
	className,
	size = "default",
	...props
}: React.ComponentProps<"div"> & { size?: "default" | "sm" }) {
	return (
		<div
			data-slot="card"
			data-size={size}
			className={cn(
				"group/card flex shadow-(--custom-shadow) flex-col gap-4 overflow-hidden rounded-lg squircle:rounded-3xl corner-squircle bg-card py-6 text-sm text-card-foreground has-[>img:first-child]:pt-0 data-[size=sm]:gap-2 data-[size=sm]:py-5 *:[img:first-child]:rounded-t-3xl *:[img:first-child]:corner-squircle *:[img:last-child]:rounded-b-3xl *:[img:last-child]:corner-squircle",
				className,
			)}
			{...props}
		/>
	);
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			data-slot="card-header"
			className={cn(
				"group/card-header @container/card-header grid auto-rows-min items-start gap-1 rounded-t-xl px-6 group-data-[size=sm]/card:px-5 has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto] [.border-b]:pb-6 group-data-[size=sm]/card:[.border-b]:pb-4",
				className,
			)}
			{...props}
		/>
	);
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			data-slot="card-title"
			className={cn(
				"font-heading text-base leading-normal font-medium group-data-[size=sm]/card:text-sm",
				className,
			)}
			{...props}
		/>
	);
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			data-slot="card-description"
			className={cn("text-sm text-muted-foreground text-balance", className)}
			{...props}
		/>
	);
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			data-slot="card-action"
			className={cn(
				"col-start-2 row-span-2 row-start-1 self-start justify-self-end",
				className,
			)}
			{...props}
		/>
	);
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			data-slot="card-content"
			className={cn("px-6 group-data-[size=sm]/card:px-5", className)}
			{...props}
		/>
	);
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			data-slot="card-footer"
			className={cn(
				"flex items-center rounded-b-xl px-6 group-data-[size=sm]/card:px-5 [.border-t]:pt-6 group-data-[size=sm]/card:[.border-t]:pt-5",
				className,
			)}
			{...props}
		/>
	);
}

export {
	Card,
	CardHeader,
	CardFooter,
	CardTitle,
	CardAction,
	CardDescription,
	CardContent,
};

"use client";

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/app/copy-icon.tsx; derived here under Apache-2.0.
 */
import { IconCircleCheckFilled, IconCopyFilled } from "@tabler/icons-react";
import { AnimatePresence, motion } from "motion/react";

import { cn } from "../../lib/utils";

export function CopyIcon({
  copied,
  className,
  checkClassName,
}: {
  copied: boolean;
  /** Classes applied to the copy icon (and the check icon unless `checkClassName` is set). */
  className?: string;
  /** Classes applied to the check icon. Defaults to `className`. */
  checkClassName?: string;
}) {
  // `relative` so the exiting (position: absolute, via popLayout) icon is pinned
  // directly over the entering one instead of momentarily stacking below it.
  return (
    <span className="relative inline-flex">
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={copied ? "check" : "copy"}
          className="inline-flex"
          initial={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
          animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
          exit={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
          transition={{ type: "spring", duration: 0.25, bounce: 0 }}
        >
          {copied ? (
            <IconCircleCheckFilled
              className={cn(
                // Page-surface greens. Inside a default-variant Button the chip's
                // bg inverts against the theme, so those call sites pass the
                // inverted pair via `checkClassName`.
                "text-green-600 dark:text-green-400",
                checkClassName ?? className
              )}
            />
          ) : (
            <IconCopyFilled className={className} />
          )}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}
